{
  "executive_summary": "The overall assessment of Northstar Manufacturing B.V. is rated as High (75.7/100), driven primarily by significant revenue concentration risk and increased financial leverage. The company's reliance on a few customers, with the largest accounting for 39% of revenue, poses a substantial risk to revenue stability. Additionally, the increase in total borrowings from EUR 21.4 million in 2024 to EUR 48.3 million in 2025 has raised concerns about financial stability, despite compliance with covenants. Mitigating factors include recent governance improvements, but the absence of an internal audit function remains a critical gap. The evidence strength is classified as strong, although there are notable gaps in cyber and legal evidence coverage.",
  "key_judgements": [
    "Northstar's revenue concentration risk is significant, with the largest customer accounting for 39% of revenue.",
    "The company's financial leverage has increased markedly, with a net debt to EBITDA ratio of 2.4x.",
    "Governance weaknesses exist due to the lack of an internal audit function and the influence of a controlling shareholder."
  ],
  "limitations": [
    "The assessment does not fully account for the long-term contract with Northstar's largest customer, which may mitigate revenue concentration risk.",
    "The impact of recent governance changes on overall effectiveness is not fully evaluated.",
    "There is incomplete evidence regarding cyber and legal risks, which may affect the overall risk profile."
  ],
  "recommended_followup": [
    "Request a detailed report on the long-term contract with the largest customer to assess its impact on revenue stability.",
    "Obtain an independent assessment of the recent governance changes to evaluate their effectiveness.",
    "Request the FY2025 audited accounts to further analyze financial stability and leverage."
  ],
  "mind_changers": [
    {
      "risk_id": "R1",
      "would_increase": "Evidence showing improved financial metrics, such as a reduction in the net debt to EBITDA ratio below 2.0x, would indicate enhanced financial stability.",
      "would_decrease": "Evidence demonstrating a significant deterioration in compliance with financial covenants or a further increase in leverage would heighten the risk assessment."
    },
    {
      "risk_id": "R2",
      "would_increase": "Evidence of a new contract or agreement with the largest customer that extends beyond December 2027 would reduce revenue concentration risk.",
      "would_decrease": "Evidence indicating that the second-largest customer's contract is not successfully renegotiated or that revenue concentration increases further would elevate the risk."
    },
    {
      "risk_id": "R3",
      "would_increase": "Evidence of further governance failures or lack of implementation of effective internal controls would heighten governance risk.",
      "would_decrease": "Evidence of successful implementation of an internal audit function and improved board independence would lower governance risk."
    }
  ]
}
